(()=>{const root=document.getElementById('avo-contact-page');if(!root)return;const chips=Array.from(root.querySelectorAll('[data-service]'));const services=root.querySelector('#ac-services');const result=root.querySelector('#ac-result');const form=root.querySelector('#ac-enquiry-form');const menu=root.querySelector('.ac-menu-button');const nav=root.querySelector('.ac-nav');
chips.forEach(chip=>chip.addEventListener('click',()=>{const selected=chip.getAttribute('aria-pressed')!=='true';if(selected){chips.forEach(other=>{if(chip.dataset.service==='Not sure yet'||other.dataset.service==='Not sure yet')other.setAttribute('aria-pressed','false')})}chip.setAttribute('aria-pressed',String(selected));services.value=chips.filter(x=>x.getAttribute('aria-pressed')==='true').map(x=>x.dataset.service).join(', ');result.hidden=true}));
menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));menu.textContent=expanded?'Close −':'Menu +';nav.classList.toggle('is-open',expanded)});
const name=root.querySelector('#ac-name'),message=root.querySelector('#ac-message');[name,message].forEach(input=>input.addEventListener('input',()=>{input.setCustomValidity('');result.hidden=true}));
form.addEventListener('submit',event=>{event.preventDefault();name.setCustomValidity(name.value.trim()?'':'Please enter your name.');message.setCustomValidity(message.value.trim()?'':'Tell us a little about your project.');if(!form.reportValidity())return;result.replaceChildren();const heading=document.createElement('strong');heading.textContent='Preview complete — your form looks ready.';const detail=document.createElement('p');detail.textContent='Nothing has been sent. In the live website, this step would submit your enquiry and show a confirmation.';result.append(heading,detail);result.hidden=false});})();
